//! Cancellation tokens and the one way exported async calls run work.
//!
//! Why a token and not just "drop the future": the Swift bindings generated by
//! `UniFFI` 0.32 never call `rust_future_cancel`, so cancelling a Swift `Task`
//! does not reach Rust on its own. Swift therefore wraps every call in
//! `withTaskCancellationHandler { … } onCancel: { token.cancel() }`, and the
//! worker polls the token between bands/tiles. Dropping the Rust future still
//! cancels too (other runtimes, tests).
//!
//! [`run_job`] guarantees:
//! - the work never runs on the polling thread (rayon pool);
//! - a panic in the work becomes `DsError::Internal`, never an abort of the app;
//! - when the future completes **or is dropped**, the worker has finished, so
//!   memory it borrowed from the caller (see `Engine::render_test_pattern_into`)
//!   is no longer touched.

use std::future::poll_fn;
use std::panic::{AssertUnwindSafe, catch_unwind};
use std::pin::Pin;
use std::sync::atomic::{AtomicBool, AtomicU8, Ordering};
use std::sync::{Arc, Condvar, Mutex, PoisonError};
use std::task::Poll;

use futures_channel::oneshot;

use crate::error::DsError;

/// Cooperative cancellation flag shared between Swift and a Rust worker.
#[derive(Debug, Default, uniffi::Object)]
pub struct CancelToken {
    cancelled: AtomicBool,
    /// Futures waiting to hear about cancellation (so a queued job can return at once).
    listeners: Mutex<Vec<oneshot::Sender<()>>>,
    /// lt-pipeline render tokens cancelled together with this one.
    linked: Mutex<Vec<lt_pipeline::CancelToken>>,
}

/// Exported surface: every call throws (C3/L12) instead of trapping Swift in `try!`.
#[uniffi::export]
impl CancelToken {
    #[uniffi::constructor(name = "new")]
    pub fn ffi_new() -> Result<Arc<Self>, DsError> {
        guard(|| Ok(Self::new()))
    }

    /// Request cancellation. Idempotent; safe from any thread.
    #[uniffi::method(name = "cancel")]
    pub fn ffi_cancel(&self) -> Result<(), DsError> {
        guard(|| {
            self.cancel();
            Ok(())
        })
    }

    #[uniffi::method(name = "is_cancelled")]
    pub fn ffi_is_cancelled(&self) -> Result<bool, DsError> {
        guard(|| Ok(self.is_cancelled()))
    }
}

impl CancelToken {
    pub fn new() -> Arc<Self> {
        Arc::new(Self::default())
    }

    /// Request cancellation. Idempotent; safe from any thread.
    pub fn cancel(&self) {
        self.cancelled.store(true, Ordering::Release);
        let listeners = std::mem::take(
            &mut *self
                .listeners
                .lock()
                .unwrap_or_else(PoisonError::into_inner),
        );
        for l in listeners {
            let _ = l.send(());
        }
        for t in std::mem::take(&mut *self.linked.lock().unwrap_or_else(PoisonError::into_inner)) {
            t.cancel();
        }
    }

    /// A lt-pipeline token cancelled when this one is (at once if it already is), so a
    /// GPU render stops between passes without polling.
    pub(crate) fn pipeline_token(&self) -> lt_pipeline::CancelToken {
        let t = lt_pipeline::CancelToken::new();
        let mut linked = self.linked.lock().unwrap_or_else(PoisonError::into_inner);
        if self.is_cancelled() {
            t.cancel();
        } else {
            linked.push(t.clone());
        }
        t
    }

    pub fn is_cancelled(&self) -> bool {
        self.cancelled.load(Ordering::Acquire)
    }
}

impl CancelToken {
    /// A receiver that resolves when the token is cancelled (at once if it already is).
    fn subscribe(&self) -> oneshot::Receiver<()> {
        let (tx, rx) = oneshot::channel();
        let mut l = self
            .listeners
            .lock()
            .unwrap_or_else(PoisonError::into_inner);
        if self.is_cancelled() {
            let _ = tx.send(());
        } else {
            l.push(tx);
        }
        rx
    }
}

/// Job lifecycle: whoever moves it out of `PENDING` first decides whether the
/// work runs (worker) or is abandoned before touching caller memory (canceller).
const PENDING: u8 = 0;
const RUNNING: u8 = 1;
const ABANDONED: u8 = 2;

/// Signals "the worker is done with borrowed memory".
#[derive(Default)]
struct Done {
    finished: Mutex<bool>,
    cv: Condvar,
}

impl Done {
    fn set(&self) {
        *self.finished.lock().unwrap_or_else(PoisonError::into_inner) = true;
        self.cv.notify_all();
    }

    fn wait(&self) {
        let mut f = self.finished.lock().unwrap_or_else(PoisonError::into_inner);
        while !*f {
            f = self.cv.wait(f).unwrap_or_else(PoisonError::into_inner);
        }
    }
}

/// On drop (future completed or abandoned): cancel and wait for the worker.
///
/// Note (L13): this cancels the caller's token even after a *successful*
/// completion. That is deliberate and harmless because tokens are per call
/// (Swift creates a fresh `CancelToken` for every async export); do not reuse
/// a token across calls.
/// The wait is short: workers check cancellation at least every band.
struct WaitForWorker {
    token: Arc<CancelToken>,
    done: Arc<Done>,
    state: Arc<AtomicU8>,
}

impl Drop for WaitForWorker {
    fn drop(&mut self) {
        self.token.cancel();
        // A job that never started will never touch borrowed memory: no wait.
        if self
            .state
            .compare_exchange(PENDING, ABANDONED, Ordering::AcqRel, Ordering::Acquire)
            .is_ok()
        {
            return;
        }
        if self.state.load(Ordering::Acquire) == RUNNING {
            self.done.wait();
        }
    }
}

/// Human-readable panic payload.
pub(crate) fn panic_message(payload: &(dyn std::any::Any + Send)) -> String {
    payload
        .downcast_ref::<&str>()
        .map(|s| (*s).to_owned())
        .or_else(|| payload.downcast_ref::<String>().cloned())
        .unwrap_or_else(|| "unknown panic".to_owned())
}

/// Run a synchronous export body, turning a panic into `DsError::Internal`
/// (C3): the generated Swift for a throwing export uses `try`, never `try!`,
/// so a Rust bug surfaces as an error instead of aborting the app.
pub(crate) fn guard<T>(f: impl FnOnce() -> Result<T, DsError>) -> Result<T, DsError> {
    catch_unwind(AssertUnwindSafe(f)).unwrap_or_else(|p| {
        Err(DsError::Internal {
            message: format!("panicked: {}", panic_message(p.as_ref())),
        })
    })
}

/// Run `work` on the rayon pool. `work` receives a `cancelled()` probe to poll.
pub(crate) async fn run_job<T, F>(token: Arc<CancelToken>, work: F) -> Result<T, DsError>
where
    T: Send + 'static,
    F: FnOnce(&dyn Fn() -> bool) -> Result<T, DsError> + Send + 'static,
{
    run_job_on(rayon::spawn, token, work).await
}

/// [`run_job`] on a thread of its own: for long background work (hashing a
/// whole folder) that must not hold one of the pool's slots for minutes.
pub(crate) async fn run_job_on_thread<T, F>(
    name: &'static str,
    token: Arc<CancelToken>,
    work: F,
) -> Result<T, DsError>
where
    T: Send + 'static,
    F: FnOnce(&dyn Fn() -> bool) -> Result<T, DsError> + Send + 'static,
{
    run_job_on(
        move |job: Job| {
            // If the thread can't be created the job is dropped, which the
            // future reports as an error (nothing ran).
            let _ = std::thread::Builder::new().name(name.into()).spawn(job);
        },
        token,
        work,
    )
    .await
}

type Job = Box<dyn FnOnce() + Send + 'static>;

/// A fixed set of named worker threads fed newest-first: bulk work (grid thumbnails)
/// runs on a few threads however many requests arrive, and the cells scrolled to last
/// are served first. Queued jobs whose caller cancelled never start (see [`run_job_on`]).
pub(crate) struct WorkerPool {
    queue: Arc<(Mutex<Vec<Job>>, Condvar)>,
}

impl WorkerPool {
    pub(crate) fn new(name: &'static str, threads: usize) -> Self {
        let queue: Arc<(Mutex<Vec<Job>>, Condvar)> = Arc::default();
        for _ in 0..threads.max(1) {
            let q = queue.clone();
            let _ = std::thread::Builder::new()
                .name(name.into())
                .spawn(move || {
                    loop {
                        let job = {
                            let (m, cv) = &*q;
                            let mut jobs = m.lock().unwrap_or_else(PoisonError::into_inner);
                            loop {
                                if let Some(j) = jobs.pop() {
                                    break j;
                                }
                                jobs = cv.wait(jobs).unwrap_or_else(PoisonError::into_inner);
                            }
                        };
                        job();
                    }
                });
        }
        Self { queue }
    }

    /// Jobs waiting for a thread (tests).
    #[cfg(test)]
    pub(crate) fn queued(&self) -> usize {
        self.queue
            .0
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .len()
    }

    fn push(&self, job: Job) {
        let (m, cv) = &*self.queue;
        m.lock().unwrap_or_else(PoisonError::into_inner).push(job);
        cv.notify_one();
    }
}

/// [`run_job`] on `pool` (newest request first).
pub(crate) async fn run_job_on_pool<T, F>(
    pool: &WorkerPool,
    token: Arc<CancelToken>,
    work: F,
) -> Result<T, DsError>
where
    T: Send + 'static,
    F: FnOnce(&dyn Fn() -> bool) -> Result<T, DsError> + Send + 'static,
{
    run_job_on(|job| pool.push(job), token, work).await
}

/// [`run_job`] with an injectable spawner (tests queue jobs deterministically).
async fn run_job_on<T, F, S>(spawn: S, token: Arc<CancelToken>, work: F) -> Result<T, DsError>
where
    T: Send + 'static,
    F: FnOnce(&dyn Fn() -> bool) -> Result<T, DsError> + Send + 'static,
    S: FnOnce(Job),
{
    if token.is_cancelled() {
        return Err(DsError::Cancelled);
    }
    let (tx, mut rx) = oneshot::channel();
    let done = Arc::new(Done::default());
    let state = Arc::new(AtomicU8::new(PENDING));
    let mut cancel_rx = token.subscribe();
    let guard = WaitForWorker {
        token: token.clone(),
        done: done.clone(),
        state: state.clone(),
    };
    let worker_state = state.clone();
    spawn(Box::new(move || {
        // Queued behind other work and cancelled meanwhile: never start.
        if worker_state
            .compare_exchange(PENDING, RUNNING, Ordering::AcqRel, Ordering::Acquire)
            .is_err()
        {
            done.set();
            return;
        }
        let result = {
            let cancelled = || token.is_cancelled() || tx.is_canceled();
            match catch_unwind(AssertUnwindSafe(|| work(&cancelled))) {
                Ok(r) => r,
                Err(p) => Err(DsError::Internal {
                    message: format!("render worker panicked: {}", panic_message(p.as_ref())),
                }),
            }
        };
        // The receiver is gone only if the future was dropped; nothing to deliver.
        let _ = tx.send(result);
        done.set();
    }));
    let result = poll_fn(|cx| {
        if let Poll::Ready(r) = Pin::new(&mut rx).poll(cx) {
            return Poll::Ready(r.unwrap_or_else(|_| {
                Err(DsError::Internal {
                    message: "worker dropped its result".into(),
                })
            }));
        }
        // Cancelled while still queued: abandon now instead of waiting for a pool slot.
        if Pin::new(&mut cancel_rx).poll(cx).is_ready()
            && state
                .compare_exchange(PENDING, ABANDONED, Ordering::AcqRel, Ordering::Acquire)
                .is_ok()
        {
            return Poll::Ready(Err(DsError::Cancelled));
        }
        Poll::Pending
    })
    .await;
    drop(guard);
    result
}

#[cfg(test)]
mod tests {
    use super::*;
    use futures_executor::block_on;
    use std::future::Future as _;
    use std::sync::atomic::AtomicUsize;
    use std::time::Duration;

    #[test]
    fn worker_pool_bounds_threads_and_serves_newest_first() {
        let pool = WorkerPool::new("lt-test-pool", 1);
        let mut cx = std::task::Context::from_waker(std::task::Waker::noop());
        // Block the single worker, queue three jobs, then release it.
        let gate = Arc::new((Mutex::new(false), Condvar::new()));
        let g = gate.clone();
        let mut blocker = Box::pin(run_job_on_pool(&pool, CancelToken::new(), move |_| {
            let (m, cv) = &*g;
            let mut open = m.lock().unwrap();
            while !*open {
                open = cv.wait(open).unwrap();
            }
            Ok(0)
        }));
        assert!(blocker.as_mut().poll(&mut cx).is_pending());
        while pool.queued() > 0 {
            std::thread::sleep(Duration::from_millis(1)); // the worker takes the blocker
        }
        let order: Arc<Mutex<Vec<i32>>> = Arc::default();
        let mut futs = Vec::new();
        for i in 1..=3 {
            let o = order.clone();
            let mut f = Box::pin(run_job_on_pool(&pool, CancelToken::new(), move |_| {
                o.lock().unwrap().push(i);
                Ok(i)
            }));
            assert!(f.as_mut().poll(&mut cx).is_pending());
            futs.push(f);
        }
        assert_eq!(pool.queued(), 3);
        *gate.0.lock().unwrap() = true;
        gate.1.notify_all();
        assert_eq!(block_on(blocker), Ok(0));
        for f in futs {
            block_on(f).unwrap();
        }
        assert_eq!(*order.lock().unwrap(), vec![3, 2, 1], "newest first");
    }

    #[test]
    fn queued_job_cancelled_returns_without_waiting_for_the_pool() {
        // A spawner that parks the job, like a saturated pool.
        let parked: Arc<Mutex<Option<Job>>> = Arc::default();
        let p2 = parked.clone();
        let ran = Arc::new(AtomicBool::new(false));
        let t = CancelToken::new();
        let ran2 = ran.clone();
        let mut fut = Box::pin(run_job_on(
            move |job| *p2.lock().unwrap() = Some(job),
            t.clone(),
            move |_| {
                ran2.store(true, Ordering::SeqCst);
                Ok(())
            },
        ));
        let mut cx = std::task::Context::from_waker(std::task::Waker::noop());
        assert!(fut.as_mut().poll(&mut cx).is_pending());
        t.cancel();
        assert_eq!(
            fut.as_mut().poll(&mut cx),
            Poll::Ready(Err(DsError::Cancelled)),
            "cancel returns while the job is still queued"
        );
        drop(fut); // must not wait for a worker that never started
        let job = parked.lock().unwrap().take().expect("job was queued");
        job(); // the pool finally gets to it
        assert!(!ran.load(Ordering::SeqCst), "an abandoned job never runs");
    }

    #[test]
    fn started_job_is_not_abandoned() {
        let parked: Arc<Mutex<Option<Job>>> = Arc::default();
        let p2 = parked.clone();
        let t = CancelToken::new();
        let mut fut = Box::pin(run_job_on(
            move |job| *p2.lock().unwrap() = Some(job),
            t.clone(),
            |cancelled| {
                if cancelled() {
                    Err(DsError::Cancelled)
                } else {
                    Ok(5)
                }
            },
        ));
        let mut cx = std::task::Context::from_waker(std::task::Waker::noop());
        assert!(fut.as_mut().poll(&mut cx).is_pending());
        let job = parked.lock().unwrap().take().unwrap();
        job();
        t.cancel();
        assert_eq!(
            fut.as_mut().poll(&mut cx),
            Poll::Ready(Ok(5)),
            "result wins once the worker ran"
        );
    }

    #[test]
    fn subscribe_after_cancel_fires_immediately() {
        let t = CancelToken::new();
        t.cancel();
        let mut rx = t.subscribe();
        assert!(matches!(rx.try_recv(), Ok(Some(()))));
    }

    #[test]
    fn token_flips_once() {
        let t = CancelToken::new();
        assert!(!t.is_cancelled());
        t.cancel();
        t.cancel();
        assert!(t.is_cancelled());
    }

    #[test]
    fn runs_off_thread_and_returns() {
        let caller = std::thread::current().id();
        let r = block_on(run_job(CancelToken::new(), move |_| {
            Ok(std::thread::current().id() != caller)
        }));
        assert_eq!(r, Ok(true));
    }

    #[test]
    fn already_cancelled_token_skips_work() {
        let t = CancelToken::new();
        t.cancel();
        let r: Result<(), _> = block_on(run_job(t, |_| panic!("must not run")));
        assert_eq!(r, Err(DsError::Cancelled));
    }

    #[test]
    fn panics_become_internal_errors() {
        let r: Result<(), _> = block_on(run_job(CancelToken::new(), |_| panic!("boom {}", 7)));
        assert_eq!(
            r,
            Err(DsError::Internal {
                message: "render worker panicked: boom 7".into()
            })
        );
        let r: Result<(), _> = block_on(run_job(CancelToken::new(), |_| {
            std::panic::panic_any(42_u8)
        }));
        assert!(
            matches!(r, Err(DsError::Internal { message }) if message.ends_with("unknown panic"))
        );
    }

    #[test]
    fn token_cancel_is_seen_by_the_worker() {
        let t = CancelToken::new();
        let seen = Arc::new(AtomicUsize::new(0));
        let (s2, t2) = (seen.clone(), t.clone());
        let fut = run_job(t.clone(), move |cancelled| {
            while !cancelled() {
                s2.fetch_add(1, Ordering::Relaxed);
                std::thread::sleep(Duration::from_millis(1));
            }
            Err::<(), _>(DsError::Cancelled)
        });
        // Cancel only once the worker is running (a still-queued job is abandoned
        // without running, which other tests cover).
        let s3 = seen.clone();
        std::thread::spawn(move || {
            while s3.load(Ordering::Relaxed) == 0 {
                std::thread::sleep(Duration::from_millis(1));
            }
            t2.cancel();
        });
        assert_eq!(block_on(fut), Err(DsError::Cancelled));
        assert!(seen.load(Ordering::Relaxed) > 0);
    }

    #[test]
    fn dropping_the_future_waits_for_the_worker() {
        let finished = Arc::new(AtomicBool::new(false));
        let started = Arc::new(AtomicBool::new(false));
        let (f2, s2) = (finished.clone(), started.clone());
        let mut fut = Box::pin(run_job(CancelToken::new(), move |cancelled| {
            s2.store(true, Ordering::Release);
            while !cancelled() {
                std::thread::sleep(Duration::from_millis(1));
            }
            std::thread::sleep(Duration::from_millis(10));
            f2.store(true, Ordering::Release);
            Ok(())
        }));
        let mut cx = std::task::Context::from_waker(std::task::Waker::noop());
        assert!(fut.as_mut().poll(&mut cx).is_pending());
        while !started.load(Ordering::Acquire) {
            std::thread::yield_now();
        }
        drop(fut);
        assert!(
            finished.load(Ordering::Acquire),
            "drop returned only after the worker let go of borrowed memory"
        );
    }

    #[test]
    fn panic_message_variants() {
        assert_eq!(panic_message(&"x"), "x");
        assert_eq!(panic_message(&String::from("y")), "y");
        assert_eq!(panic_message(&1_i32), "unknown panic");
    }

    #[test]
    fn pipeline_tokens_follow_cancellation() {
        let t = CancelToken::new();
        let a = t.pipeline_token();
        assert!(!a.is_cancelled());
        t.cancel();
        assert!(a.is_cancelled(), "linked before the cancel");
        assert!(t.pipeline_token().is_cancelled(), "linked after the cancel");
    }

    #[test]
    fn guard_turns_panics_into_internal_errors() {
        assert_eq!(guard(|| Ok(3)), Ok(3));
        assert_eq!(
            guard::<()>(|| Err(DsError::Cancelled)),
            Err(DsError::Cancelled)
        );
        let r: Result<(), _> = guard(|| panic!("sync bug"));
        assert_eq!(
            r,
            Err(DsError::Internal {
                message: "panicked: sync bug".into()
            })
        );
    }
}
